INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredItemId1`, `RequiredItemCount1`, `RewardNextQuest`) VALUES (59929, 2, 1, 1, 2, 0, 'Murloc Mania / 鱼人狂潮', 'Recover 6 First Aid Kits from Murlocs. / 从鱼人手中夺回6个急救包。', 'The shore is littered with shipwrecks. This must be where the lost expedition crashed.$B$BWe''ll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up.$B$BSlay those murlocs to get back what belongs to the Horde.$B$B海岸上到处是沉船残骸，这里一定就是失落远征队坠毁的地方。$B$B我们需要更多补给来帮助伤员康复。附近的鱼人偷走了大部分冲上岸的东西。$B$B杀死那些鱼人，把属于部落的东西夺回来。', 'Bring 6 First Aid Kits to Thrall. / 把6个急救包交给萨尔。', '', 170549, 6, 0);
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `StartItem`, `ItemDrop1`, `ItemDropQuantity1`, `RequiredNpcOrGo1`, `RequiredNpcOrGo2`, `RequiredNpcOrGo3`, `RequiredNpcOrGoCount1`, `RequiredNpcOrGoCount2`, `RequiredNpcOrGoCount3`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`) VALUES (59930, 2, 1, 1, 2, 0, 'Emergency First Aid / 紧急急救', 'Use a First Aid Kit on Bo, Mithdran Dawntracker, and Lana Jordan. / 对波、米斯德兰·晨踪者和拉娜·乔丹使用急救包。', 'We must treat our wounded before we can begin for the missing expedition.$B$BTake this first aid kit and tend to the survivors. I''ll handle the others nearby.$B$B我们必须先救治伤员，才能去寻找失踪的远征队。$B$B拿着这个急救包，去照看幸存者。附近的其他人我来处理。', 'Use the First Aid Kit on the three survivors. / 对三名幸存者使用急救包。', '', 168410, 168410, 1, 166796, 166786, 166791, 1, 1, 1, 'First Aid Kit used on Lana Jordan / 已对拉娜·乔丹使用急救包', 'First Aid Kit used on Bo / 已对波使用急救包', 'First Aid Kit used on Mithdran Dawntracker / 已对米斯德兰·晨踪者使用急救包');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`) VALUES (59931, 2, 1, 1, 1, 0, 'Finding the Lost Expedition / 寻找失落的远征队', 'Search the nearby camp for expedition survivors. / 在附近的营地搜寻远征队幸存者。', 'Breka Grimaxe went north to look for survivors. Join her to see what she''s found.$B$BI''m going to go up ahead to see if I can find anyone else. We''ll meet again further within the island.$B$B布蕾卡·格里马克斯往北去寻找幸存者了。去和她会合，看看她发现了什么。$B$B我先去前面看看能不能找到其他人。我们在岛的更深处再会合。', 'Speak with Won''sa or Thrall within the Abandoned Camp. / 在废弃营地里与旺萨或萨尔交谈。', '');
