INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59929, 0, 0, 'The murlocs are carrying our first aid kits. Slay them and bring all of the kits to me.$B$B鱼人身上带着我们的急救包。杀了它们，把所有急救包都带给我。', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59930, 0, 0, 'Have you treated all of the survivors yet?$B$B你给所有幸存者都治疗过了吗？', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59929, 1, 0, 0, 0, 'Good work. These will keep the wounded alive.$B$B干得好。这些能让伤员活下去。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59930, 1, 0, 0, 0, 'You''ve done well. Now we can move on and look for the others.$B$B你做得很好。现在我们可以动身去找其他人了。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59931, 1, 0, 0, 0, 'You made it. We found signs of the expedition, but there is more to see further in.$B$B你们来了。我们发现了远征队的踪迹，但再往里还有更多线索。', 0);
