-- BEACH1A V1 (2026-11-23, Claude): Exile's Reach beach quests 59929 Murloc Mania / 59930 Emergency First Aid / 59931 Finding the Lost Expedition.
-- Data from LoreWalkerTDB (12.x) re-built for AC 3.3.5: NPC entries, quest text, spawn positions are retail; models are 3.3.5 stand-ins; Chinese text is Claude's own.
-- Safe to run twice. Creature guids are taken from the live legal maximum + 1 (must stay below 16777215). Keep worldserver stopped.
SET @spawn_limit := 16777215;

DELETE FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1A %';
DELETE FROM `creature_template` WHERE `entry` IN (166782,166906,166854,166786,166791,166796,150228,150229);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (166782,166906,166854,166786,166791,166796,150228,150229);
DELETE FROM `creature_loot_template` WHERE `Entry` IN (150228, 150229);
DELETE FROM `item_template` WHERE `entry` IN (168410, 170549);
DELETE FROM `quest_template` WHERE `ID` IN (59929,59930,59931);
DELETE FROM `quest_template_addon` WHERE `ID` IN (59929,59930,59931);
DELETE FROM `quest_offer_reward` WHERE `ID` IN (59929,59930,59931);
DELETE FROM `quest_request_items` WHERE `ID` IN (59929,59930,59931);
DELETE FROM `creature_queststarter` WHERE `quest` IN (59929,59930,59931);
DELETE FROM `creature_questender` WHERE `quest` IN (59929,59930,59931);
SELECT COALESCE(MAX(`guid`), 0) INTO @g FROM `creature` WHERE `guid` < @spawn_limit;





DELETE FROM `creature_template_addon` WHERE `entry` IN (166786, 166791, 166796);

SELECT IF(@g + 45 + 10000 < @spawn_limit, 'guid base OK', 'ABORT: no guid room, do not continue') AS guid_check, @g AS legal_max_guid;







SELECT `guid`, `id1`, `position_x`, `position_y`, `position_z` FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1A fixed' ORDER BY `guid`;
SELECT COUNT(*) AS beach1a_spawns FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1A %';
SELECT MAX(`guid`) AS max_guid_after, SUM(`guid` >= @spawn_limit) AS invalid_guids_after FROM `creature`;
